insert into public.exercises (id, name, muscle_group, equipment, demo, steps, sort_order)
values
  ('bench-press', 'Barbell Bench Press', 'chest', 'Barbell', 'Barbell_Bench_Press_-_Medium_Grip', array['Lie flat with your eyes under the bar and plant both feet.', 'Grip slightly wider than shoulder-width, wrists stacked over elbows.', 'Unrack, then lower the bar under control to mid-chest.', 'Keep your elbows about 45° from your body — not flared straight out.', 'Press back up until your arms are locked, without bouncing off your chest.']::text[], 0),
  ('incline-bench-press', 'Incline Barbell Bench Press', 'chest', 'Barbell', 'Barbell_Incline_Bench_Press_-_Medium_Grip', array['Set the bench to roughly 30° — steeper shifts the work to your shoulders.', 'Grip slightly wider than shoulder-width and unrack.', 'Lower the bar to your upper chest, just below the collarbone.', 'Press up and slightly back, finishing over your shoulders.']::text[], 1),
  ('decline-bench-press', 'Decline Barbell Bench Press', 'chest', 'Barbell', 'Decline_Barbell_Bench_Press', array['Secure your legs in the pads before unracking.', 'Grip slightly wider than shoulder-width.', 'Lower the bar to your lower chest under control.', 'Press back up to locked arms, keeping your head down on the bench.']::text[], 2),
  ('db-bench-press', 'Dumbbell Bench Press', 'chest', 'Dumbbell', 'Dumbbell_Bench_Press', array['Sit with the dumbbells on your thighs, then kick them up as you lie back.', 'Start with the weights at chest level, palms facing forward.', 'Press up until your arms are straight, letting the dumbbells drift together.', 'Lower slowly until you feel a stretch across your chest.']::text[], 3),
  ('incline-db-press', 'Incline Dumbbell Press', 'chest', 'Dumbbell', 'Incline_Dumbbell_Press', array['Set the bench to about 30° and sit back with the dumbbells on your thighs.', 'Start at upper-chest level with palms facing forward.', 'Press up and slightly inward until your arms lock out.', 'Lower under control until your elbows sit just below shoulder height.']::text[], 4),
  ('db-fly', 'Dumbbell Fly', 'chest', 'Dumbbell', 'Dumbbell_Flyes', array['Lie flat holding the dumbbells above your chest, palms facing each other.', 'Keep a soft, fixed bend in your elbows for the whole set.', 'Open your arms in a wide arc until you feel a stretch across your chest.', 'Bring them back together along the same arc — hug, don’t press.', 'Use a lighter weight than you would for a press; this is a stretch, not a lift.']::text[], 5),
  ('cable-crossover', 'Cable Crossover', 'chest', 'Cable', 'Cable_Crossover', array['Set both pulleys high and take a handle in each hand.', 'Step forward into a split stance with a slight forward lean.', 'Keep a soft bend in the elbows and sweep your hands down and together.', 'Cross slightly at the bottom, squeeze, then return slowly.']::text[], 6),
  ('pec-deck', 'Pec Deck Machine', 'chest', 'Machine', 'Butterfly', array['Set the seat so the handles sit at chest height.', 'Sit back with your shoulders down and your back against the pad.', 'Bring the handles together in front of your chest and squeeze.', 'Return slowly until you feel a stretch, without letting the weights touch down.']::text[], 7),
  ('push-up', 'Push-Up', 'chest', 'Bodyweight', 'Pushups', array['Set your hands slightly wider than your shoulders.', 'Brace your abs and glutes so your body is one straight line.', 'Lower until your chest is just above the floor, elbows about 45°.', 'Press back up without letting your hips sag or pike.']::text[], 8),
  ('dips-chest', 'Chest Dip', 'chest', 'Bodyweight', 'Dips_-_Chest_Version', array['Support yourself on the bars with your arms locked.', 'Lean your torso forward — that’s what shifts the work to your chest.', 'Lower until your upper arms are roughly parallel to the floor.', 'Press back up, keeping the forward lean throughout.', 'Stop short if you feel it pinch at the front of the shoulder.']::text[], 9),
  ('machine-chest-press', 'Machine Chest Press', 'chest', 'Machine', 'Leverage_Chest_Press', array['Set the seat so the handles line up with the middle of your chest.', 'Sit back with your shoulders down and pinned to the pad.', 'Press forward until your arms are straight but not locked hard.', 'Return under control until your hands are level with your chest.']::text[], 10),
  ('deadlift', 'Conventional Deadlift', 'back', 'Barbell', 'Barbell_Deadlift', array['Stand with the bar over your mid-foot, feet about hip-width.', 'Hinge and grip just outside your knees; shins lightly touch the bar.', 'Set your chest up and pull the slack out of the bar before you lift.', 'Drive through the floor, keeping the bar dragging up your legs.', 'Lock out by standing tall — don’t lean back at the top.']::text[], 11),
  ('sumo-deadlift', 'Sumo Deadlift', 'back', 'Barbell', 'Sumo_Deadlift', array['Take a wide stance with your toes turned out, bar over mid-foot.', 'Grip inside your knees with your arms hanging straight down.', 'Drop your hips, open your knees out over your toes, chest up.', 'Push the floor apart and stand, keeping the bar close.']::text[], 12),
  ('romanian-deadlift', 'Romanian Deadlift', 'back', 'Barbell', 'Romanian_Deadlift', array['Start standing with the bar at your hips, knees softly bent.', 'Push your hips backwards and let the bar slide down your thighs.', 'Stop when you feel a strong stretch in your hamstrings — usually mid-shin.', 'Keep your back flat the whole way; the knees barely move.', 'Drive your hips forward to stand back up.']::text[], 13),
  ('pull-up', 'Pull-Up', 'back', 'Bodyweight', 'Pullups', array['Grip the bar just wider than your shoulders, palms facing away.', 'Start from a full hang, then pull your shoulder blades down first.', 'Drive your elbows to your ribs until your chin clears the bar.', 'Lower all the way under control rather than dropping.']::text[], 14),
  ('chin-up', 'Chin-Up', 'back', 'Bodyweight', 'Chin-Up', array['Grip the bar shoulder-width with your palms facing you.', 'Hang fully, then pull your chest towards the bar.', 'Keep your elbows tucked in front of you as you rise.', 'Lower slowly to a full hang between reps.']::text[], 15),
  ('lat-pulldown', 'Lat Pulldown', 'back', 'Cable', 'Wide-Grip_Lat_Pulldown', array['Set the thigh pad so you stay seated when the weight gets heavy.', 'Grip wider than shoulder-width and lean back very slightly.', 'Pull the bar to your upper chest, leading with your elbows.', 'Squeeze your shoulder blades together, then return with control.', 'Don’t pull behind your neck — it stresses the shoulder for no extra benefit.']::text[], 16),
  ('barbell-row', 'Bent-Over Barbell Row', 'back', 'Barbell', 'Bent_Over_Barbell_Row', array['Hinge forward to roughly 45° with a flat back and soft knees.', 'Grip just outside your knees, arms hanging straight down.', 'Pull the bar to your lower ribs, elbows going back not out.', 'Lower under control without letting your torso rise.']::text[], 17),
  ('pendlay-row', 'Pendlay Row', 'back', 'Barbell', null, array['Set up like a bent-over row but with your torso parallel to the floor.', 'The bar starts on the floor and returns to it every rep.', 'Pull explosively to your lower chest, keeping your back flat and still.', 'Reset the bar on the floor between reps — no bouncing.']::text[], 18),
  ('db-row', 'Single-Arm Dumbbell Row', 'back', 'Dumbbell', 'One-Arm_Dumbbell_Row', array['Put one knee and the same-side hand on a bench, back flat.', 'Let the dumbbell hang straight down from your free arm.', 'Pull it to your hip, driving your elbow past your ribs.', 'Lower all the way to a full stretch, keeping your shoulders level.']::text[], 19),
  ('seated-cable-row', 'Seated Cable Row', 'back', 'Cable', 'Seated_Cable_Rows', array['Sit with a slight knee bend and your chest tall.', 'Start with your arms extended and shoulder blades stretched forward.', 'Pull the handle to your navel, elbows brushing your sides.', 'Squeeze your shoulder blades, then extend slowly without slumping.']::text[], 20),
  ('t-bar-row', 'T-Bar Row', 'back', 'Barbell', 'T-Bar_Row_with_Handle', array['Straddle the bar and hinge forward with a flat back.', 'Take the handle with both hands and let it hang.', 'Row towards your stomach, keeping your elbows close.', 'Lower to a full stretch without rounding your lower back.']::text[], 21),
  ('face-pull', 'Face Pull', 'back', 'Cable', 'Face_Pull', array['Set a rope attachment at roughly head height.', 'Take an overhand grip and step back until the cable is tight.', 'Pull the rope towards your forehead, splitting your hands apart.', 'Finish with your knuckles by your ears and elbows high.', 'Go light — this is a control exercise for the rear shoulder.']::text[], 22),
  ('straight-arm-pulldown', 'Straight-Arm Pulldown', 'back', 'Cable', 'Straight-Arm_Pulldown', array['Stand facing a high pulley with a bar or rope, arms extended.', 'Hinge forward slightly and lock a soft bend into your elbows.', 'Sweep the bar down in an arc until it reaches your thighs.', 'Return slowly overhead, feeling the stretch through your lats.']::text[], 23),
  ('overhead-press', 'Standing Overhead Press', 'shoulders', 'Barbell', 'Standing_Military_Press', array['Start with the bar on your front shoulders, grip just outside shoulder-width.', 'Squeeze your glutes and brace so you don’t lean back.', 'Press straight up, moving your head back slightly to clear the bar.', 'Lock out with the bar over your mid-foot, ears in front of your arms.', 'Lower under control back to your shoulders.']::text[], 24),
  ('seated-db-press', 'Seated Dumbbell Shoulder Press', 'shoulders', 'Dumbbell', 'Seated_Dumbbell_Press', array['Sit with your back against an upright bench, feet planted.', 'Start with the dumbbells at ear height, palms forward.', 'Press up and slightly together until your arms lock.', 'Lower under control until your elbows are just below shoulder height.']::text[], 25),
  ('arnold-press', 'Arnold Press', 'shoulders', 'Dumbbell', 'Arnold_Dumbbell_Press', array['Start with the dumbbells in front of your chest, palms facing you.', 'As you press, rotate your palms to face forward.', 'Finish locked out overhead with the weights slightly together.', 'Reverse the rotation on the way down — smooth, not rushed.']::text[], 26),
  ('lateral-raise', 'Dumbbell Lateral Raise', 'shoulders', 'Dumbbell', 'Side_Lateral_Raise', array['Stand with the dumbbells at your sides, elbows slightly bent.', 'Raise your arms out to the sides until they reach shoulder height.', 'Lead with your elbows, not your hands.', 'Lower slowly — most of the benefit is on the way down.', 'Use light weight; swinging turns this into a shrug.']::text[], 27),
  ('cable-lateral-raise', 'Cable Lateral Raise', 'shoulders', 'Cable', 'Cable_Seated_Lateral_Raise', array['Set the pulley to its lowest point and stand side-on.', 'Take the handle in the outside hand, across your body.', 'Raise your arm out to the side to shoulder height.', 'Lower slowly against the cable’s pull, keeping tension throughout.']::text[], 28),
  ('front-raise', 'Dumbbell Front Raise', 'shoulders', 'Dumbbell', 'Front_Dumbbell_Raise', array['Hold the dumbbells in front of your thighs, palms facing you.', 'Raise one or both arms straight out in front to shoulder height.', 'Keep your torso still — no rocking to get the weight up.', 'Lower under control to the start.']::text[], 29),
  ('rear-delt-fly', 'Rear Delt Fly', 'shoulders', 'Dumbbell', 'Reverse_Flyes', array['Hinge forward until your chest is near parallel to the floor.', 'Let the dumbbells hang below you, elbows slightly bent.', 'Open your arms out to the sides, squeezing your shoulder blades.', 'Stop at shoulder height, then lower slowly.']::text[], 30),
  ('upright-row', 'Upright Row', 'shoulders', 'Barbell', 'Upright_Barbell_Row', array['Grip the bar at about shoulder-width — narrower can pinch the shoulder.', 'Pull the bar up the front of your body, leading with your elbows.', 'Stop when your upper arms reach shoulder height.', 'Lower under control; stop the set if you feel any shoulder pinch.']::text[], 31),
  ('barbell-shrug', 'Barbell Shrug', 'shoulders', 'Barbell', 'Barbell_Shrug', array['Hold the bar at arm’s length in front of your thighs.', 'Shrug straight up towards your ears, arms staying straight.', 'Pause briefly at the top and squeeze.', 'Lower fully — don’t roll your shoulders.']::text[], 32),
  ('machine-shoulder-press', 'Machine Shoulder Press', 'shoulders', 'Machine', 'Machine_Shoulder_Military_Press', array['Set the seat so the handles start at about ear height.', 'Sit back with your back flat against the pad.', 'Press up until your arms are straight but not locked hard.', 'Lower under control to the starting height.']::text[], 33),
  ('barbell-curl', 'Barbell Curl', 'arms', 'Barbell', 'Barbell_Curl', array['Stand with the bar at arm’s length, palms facing forward.', 'Keep your elbows pinned at your sides throughout.', 'Curl the bar up to shoulder height without swinging.', 'Lower slowly to a full stretch at the bottom.']::text[], 34),
  ('ez-bar-curl', 'EZ-Bar Curl', 'arms', 'Barbell', 'EZ-Bar_Curl', array['Take the angled part of the bar — it’s easier on the wrists.', 'Keep your elbows tight to your ribs.', 'Curl up to shoulder height, squeezing at the top.', 'Lower under control until your arms are straight.']::text[], 35),
  ('db-curl', 'Dumbbell Curl', 'arms', 'Dumbbell', 'Dumbbell_Bicep_Curl', array['Stand with the dumbbells at your sides, palms facing forward.', 'Curl one or both up, keeping your elbows still.', 'Squeeze at the top without swinging your shoulders forward.', 'Lower all the way down before the next rep.']::text[], 36),
  ('hammer-curl', 'Hammer Curl', 'arms', 'Dumbbell', 'Alternate_Hammer_Curl', array['Hold the dumbbells with palms facing each other, like holding hammers.', 'Keep that neutral grip for the whole rep.', 'Curl up towards your shoulder, elbow staying at your side.', 'Lower under control, then repeat on the other arm.']::text[], 37),
  ('incline-db-curl', 'Incline Dumbbell Curl', 'arms', 'Dumbbell', 'Incline_Dumbbell_Curl', array['Set a bench to about 60° and sit back with your arms hanging.', 'Let the dumbbells stretch behind your torso — that’s the point of the angle.', 'Curl up without letting your elbows drift forward.', 'Lower all the way back to the stretch.']::text[], 38),
  ('preacher-curl', 'Preacher Curl', 'arms', 'Barbell', 'Preacher_Curl', array['Set the seat so your armpits rest on the top of the pad.', 'Rest the backs of your arms flat against the pad.', 'Curl up to just short of vertical, where tension drops off.', 'Lower slowly — never let the weight snap your elbows straight.']::text[], 39),
  ('concentration-curl', 'Concentration Curl', 'arms', 'Dumbbell', 'Concentration_Curls', array['Sit and brace the back of your upper arm against your inner thigh.', 'Let the dumbbell hang at a full stretch.', 'Curl up towards your opposite shoulder, squeezing hard at the top.', 'Lower slowly and repeat before switching arms.']::text[], 40),
  ('cable-curl', 'Cable Curl', 'arms', 'Cable', 'Standing_Biceps_Cable_Curl', array['Set the pulley low and stand a step back from the machine.', 'Keep your elbows at your sides and your torso upright.', 'Curl the bar to shoulder height against constant cable tension.', 'Lower slowly without letting the stack touch down.']::text[], 41),
  ('tricep-pushdown', 'Tricep Pushdown', 'arms', 'Cable', 'Triceps_Pushdown', array['Set the pulley high and grip the bar with palms down.', 'Tuck your elbows against your ribs and lean in very slightly.', 'Push down until your arms are fully straight.', 'Let the bar rise to about 90° — no further, or your elbows drift.']::text[], 42),
  ('rope-pushdown', 'Rope Tricep Pushdown', 'arms', 'Cable', 'Triceps_Pushdown_-_Rope_Attachment', array['Set the pulley high and take a rope with a neutral grip.', 'Keep your elbows pinned at your sides.', 'Push down and split the rope apart at the bottom.', 'Return under control to about 90° at the elbow.']::text[], 43),
  ('skull-crusher', 'Skull Crusher', 'arms', 'Barbell', 'EZ-Bar_Skullcrusher', array['Lie on a flat bench holding an EZ-bar above your chest.', 'Keep your upper arms still and angled slightly back.', 'Bend at the elbows to lower the bar towards your forehead.', 'Extend back up without letting your elbows flare wide.']::text[], 44),
  ('overhead-tricep-ext', 'Overhead Tricep Extension', 'arms', 'Dumbbell', 'Standing_Dumbbell_Triceps_Extension', array['Hold one dumbbell overhead with both hands, arms straight.', 'Keep your elbows pointing forward and close to your head.', 'Lower the weight behind your head until you feel a stretch.', 'Extend back to straight without letting your ribs flare.']::text[], 45),
  ('close-grip-bench', 'Close-Grip Bench Press', 'arms', 'Barbell', 'Close-Grip_Barbell_Bench_Press', array['Grip the bar at about shoulder-width — no narrower.', 'Lower to your lower chest with your elbows tucked close.', 'Keep your wrists stacked over your elbows.', 'Press back up, driving through your triceps.']::text[], 46),
  ('tricep-dip', 'Tricep Dip', 'arms', 'Bodyweight', 'Dips_-_Triceps_Version', array['Support yourself on the bars with your torso upright.', 'Keep your elbows pointing straight back, not out.', 'Lower until your upper arms are about parallel to the floor.', 'Press back to locked arms, staying tall throughout.']::text[], 47),
  ('back-squat', 'Barbell Back Squat', 'legs', 'Barbell', 'Barbell_Squat', array['Set the bar across your upper back, not on your neck.', 'Unrack, step back, and set your feet about shoulder-width, toes slightly out.', 'Brace your core, then sit down and back, knees tracking over your toes.', 'Descend to at least parallel if your hips allow it.', 'Drive up through your mid-foot, keeping your chest up.']::text[], 48),
  ('front-squat', 'Barbell Front Squat', 'legs', 'Barbell', 'Front_Barbell_Squat', array['Rest the bar on your front shoulders with your elbows high.', 'Keep your elbows up for the whole rep — dropping them dumps the bar.', 'Sit straight down with an upright torso.', 'Drive back up without letting your chest fall forward.']::text[], 49),
  ('goblet-squat', 'Goblet Squat', 'legs', 'Dumbbell', 'Goblet_Squat', array['Hold a dumbbell or kettlebell against your chest with both hands.', 'Stand a little wider than shoulder-width, toes slightly out.', 'Squat down between your knees, keeping your chest tall.', 'Push the floor away to stand, keeping the weight close.']::text[], 50),
  ('hack-squat', 'Hack Squat', 'legs', 'Machine', 'Hack_Squat', array['Set your shoulders under the pads and your feet mid-platform.', 'Release the safeties and take the weight.', 'Lower until your knees reach about 90°.', 'Press back up without locking your knees hard at the top.']::text[], 51),
  ('leg-press', 'Leg Press', 'legs', 'Machine', 'Leg_Press', array['Sit back fully so your lower back stays flat against the pad.', 'Place your feet shoulder-width in the middle of the platform.', 'Lower until your knees reach about 90°, keeping your hips down.', 'Press back up without locking your knees out hard.']::text[], 52),
  ('bulgarian-split-squat', 'Bulgarian Split Squat', 'legs', 'Dumbbell', 'Split_Squat_with_Dumbbells', array['Rest the top of your back foot on a bench behind you.', 'Step the front foot far enough forward to keep the knee behind the toes.', 'Lower straight down until your back knee nearly touches the floor.', 'Drive up through your front heel; finish all reps before swapping.']::text[], 53),
  ('walking-lunge', 'Walking Lunge', 'legs', 'Dumbbell', 'Barbell_Walking_Lunge', array['Stand tall holding the weight at your sides or on your back.', 'Step forward and lower until both knees are at about 90°.', 'Push off your back foot and step straight into the next lunge.', 'Keep your torso upright and your steps in a straight line.']::text[], 54),
  ('reverse-lunge', 'Reverse Lunge', 'legs', 'Dumbbell', 'Dumbbell_Rear_Lunge', array['Stand tall with the weights at your sides.', 'Step backwards and lower until both knees reach about 90°.', 'Keep most of your weight on the front leg.', 'Push through the front heel to return to standing.']::text[], 55),
  ('step-up', 'Step-Up', 'legs', 'Dumbbell', 'Dumbbell_Step_Ups', array['Pick a box that puts your thigh roughly parallel when you step up.', 'Place one whole foot on the box.', 'Drive through that heel to stand up — don’t push off the back foot.', 'Lower back down under control rather than dropping.']::text[], 56),
  ('leg-extension', 'Leg Extension', 'legs', 'Machine', 'Leg_Extensions', array['Set the pad so it sits on your shins just above your ankles.', 'Line the machine’s pivot up with your knee joint.', 'Extend until your legs are straight and squeeze briefly.', 'Lower slowly without letting the weights slam down.']::text[], 57),
  ('lying-leg-curl', 'Lying Leg Curl', 'legs', 'Machine', 'Lying_Leg_Curls', array['Lie face down with the pad just above your heels.', 'Hold the handles and keep your hips pressed into the bench.', 'Curl your heels towards your glutes as far as they’ll go.', 'Lower slowly to a full stretch.']::text[], 58),
  ('seated-leg-curl', 'Seated Leg Curl', 'legs', 'Machine', 'Seated_Leg_Curl', array['Set the lap pad snug so you stay in the seat.', 'Place the pad against the backs of your lower calves.', 'Curl your heels down and under, squeezing your hamstrings.', 'Return slowly to straight legs.']::text[], 59),
  ('hip-thrust', 'Barbell Hip Thrust', 'legs', 'Barbell', 'Barbell_Hip_Thrust', array['Sit with your upper back against a bench and the bar over your hips.', 'Plant your feet so your shins are vertical at the top.', 'Drive through your heels and squeeze your glutes to lift the bar.', 'Finish with your torso parallel to the floor and your ribs down.', 'Lower under control without resting the bar on the floor.']::text[], 60),
  ('standing-calf-raise', 'Standing Calf Raise', 'legs', 'Machine', 'Standing_Calf_Raises', array['Stand with the balls of your feet on the platform, heels hanging off.', 'Drop your heels below the step for a full stretch.', 'Press up onto your toes as high as you can.', 'Pause at the top, then lower slowly — don’t bounce.']::text[], 61),
  ('seated-calf-raise', 'Seated Calf Raise', 'legs', 'Machine', 'Seated_Calf_Raise', array['Sit with the pad across your lower thighs, balls of your feet on the step.', 'Release the safety and let your heels drop for a stretch.', 'Press up onto your toes as far as the machine allows.', 'Pause at the top, then lower slowly.']::text[], 62),
  ('good-morning', 'Good Morning', 'legs', 'Barbell', 'Good_Morning', array['Set a light bar across your upper back and unrack it.', 'Soften your knees and brace your core hard.', 'Push your hips back and hinge forward with a flat back.', 'Stop when your hamstrings tighten, then drive your hips forward to stand.', 'Start much lighter than you think — this one punishes ego.']::text[], 63),
  ('plank', 'Plank', 'core', 'Bodyweight', 'Plank', array['Rest on your forearms with your elbows under your shoulders.', 'Extend your legs and come up onto your toes.', 'Squeeze your glutes and abs so your body is one straight line.', 'Don’t let your hips sag or pike up — hold and breathe steadily.']::text[], 64),
  ('side-plank', 'Side Plank', 'core', 'Bodyweight', 'Side_Bridge', array['Lie on your side with your elbow directly under your shoulder.', 'Stack your feet and lift your hips off the floor.', 'Form a straight line from ankles to head.', 'Hold, then repeat on the other side for the same time.']::text[], 65),
  ('crunch', 'Crunch', 'core', 'Bodyweight', 'Crunches', array['Lie on your back with your knees bent and feet flat.', 'Rest your hands by your ears without pulling on your neck.', 'Curl your shoulders up off the floor, ribs towards hips.', 'Lower slowly — this is a short movement, not a full sit-up.']::text[], 66),
  ('bicycle-crunch', 'Bicycle Crunch', 'core', 'Bodyweight', 'Air_Bike', array['Lie on your back with your hands lightly by your ears.', 'Lift your shoulders and bring both knees up.', 'Rotate one elbow towards the opposite knee as the other leg extends.', 'Alternate smoothly — control beats speed here.']::text[], 67),
  ('hanging-leg-raise', 'Hanging Leg Raise', 'core', 'Bodyweight', 'Hanging_Leg_Raise', array['Hang from a bar with your arms straight and shoulders engaged.', 'Without swinging, raise your legs until your hips curl up.', 'Pause at the top rather than using momentum.', 'Lower slowly and fully between reps.']::text[], 68),
  ('lying-leg-raise', 'Lying Leg Raise', 'core', 'Bodyweight', 'Flat_Bench_Lying_Leg_Raise', array['Lie flat and tuck your hands under your hips for support.', 'Press your lower back into the floor or bench.', 'Raise your legs to vertical, keeping them nearly straight.', 'Lower slowly and stop before your back arches off.']::text[], 69),
  ('russian-twist', 'Russian Twist', 'core', 'Dumbbell', 'Russian_Twist', array['Sit with your knees bent and lean back to about 45°.', 'Hold a weight at your chest, feet lifted if you can.', 'Rotate your torso to tap the weight beside one hip.', 'Rotate to the other side — turn your shoulders, not just your arms.']::text[], 70),
  ('cable-crunch', 'Cable Crunch', 'core', 'Cable', 'Cable_Crunch', array['Kneel below a high pulley holding a rope beside your head.', 'Keep your hips fixed — they shouldn’t move at all.', 'Curl your ribs down towards your knees, rounding your upper back.', 'Return slowly against the weight.']::text[], 71),
  ('ab-wheel', 'Ab Wheel Rollout', 'core', 'Other', 'Ab_Roller', array['Kneel with the wheel under your shoulders.', 'Brace your abs and squeeze your glutes before you move.', 'Roll forward only as far as you can go without your hips sagging.', 'Pull back using your abs, not your arms.', 'Shorten the range if your lower back starts to arch.']::text[], 72),
  ('mountain-climber', 'Mountain Climber', 'core', 'Bodyweight', 'Mountain_Climbers', array['Start in a push-up position with your hands under your shoulders.', 'Drive one knee towards your chest.', 'Switch legs quickly, keeping your hips low and level.', 'Keep your shoulders stacked over your hands throughout.']::text[], 73),
  ('dead-bug', 'Dead Bug', 'core', 'Bodyweight', 'Dead_Bug', array['Lie on your back with arms up and knees bent at 90°.', 'Press your lower back flat into the floor and keep it there.', 'Lower one arm and the opposite leg towards the floor.', 'Return and swap sides — stop as soon as your back lifts.']::text[], 74),
  ('treadmill-run', 'Treadmill Run', 'cardio', 'Machine', 'Running_Treadmill', array['Start with a few minutes of walking to warm up.', 'Build to your target pace rather than jumping straight in.', 'Stay in the middle of the belt and look ahead, not down.', 'Keep your steps light and let your arms swing naturally.', 'Finish with a slow walk to bring your heart rate down.']::text[], 75),
  ('outdoor-run', 'Outdoor Run', 'cardio', 'Bodyweight', null, array['Start with five minutes of easy jogging to warm up.', 'Hold a pace where you could still speak in short sentences.', 'Keep your steps light and land under your body, not out in front.', 'Stay relaxed through the shoulders and hands.', 'Ease down to a walk at the end rather than stopping dead.']::text[], 76),
  ('cycling', 'Stationary Bike', 'cardio', 'Machine', 'Bicycling_Stationary', array['Set the saddle so your knee stays slightly bent at the bottom.', 'Warm up for a few minutes at light resistance.', 'Keep a smooth cadence rather than stamping the pedals.', 'Stay seated with a relaxed grip and a neutral back.']::text[], 77),
  ('rowing-machine', 'Rowing Machine', 'cardio', 'Machine', 'Rowing_Stationary', array['Strap your feet in and start with your shins vertical.', 'Drive with your legs first, then lean back, then pull with your arms.', 'Reverse that order on the way back: arms, body, legs.', 'Keep your back flat throughout — the legs do most of the work.']::text[], 78),
  ('elliptical', 'Elliptical Trainer', 'cardio', 'Machine', 'Elliptical_Trainer', array['Step on and hold the moving handles.', 'Start slow to find the rhythm before adding resistance.', 'Stand tall and keep your whole foot on the pedal.', 'Push and pull with your arms rather than just hanging on.']::text[], 79),
  ('stair-climber', 'Stair Climber', 'cardio', 'Machine', 'Stairmaster', array['Start at a slow speed and step on before it builds up.', 'Stand upright — don’t lean your weight onto the handrails.', 'Take full steps rather than short bouncy ones.', 'Rest a hand on the rail for balance only.']::text[], 80),
  ('jump-rope', 'Jump Rope', 'cardio', 'Other', 'Rope_Jumping', array['Size the rope so the handles reach your armpits when you stand on it.', 'Keep your elbows close and turn the rope with your wrists.', 'Jump just high enough to clear it — a couple of centimetres.', 'Land softly on the balls of your feet.']::text[], 81),
  ('burpee', 'Burpee', 'cardio', 'Bodyweight', null, array['Start standing, then squat down and place your hands on the floor.', 'Jump or step your feet back into a push-up position.', 'Do a push-up if you want the full version, then jump your feet back in.', 'Stand and jump with your hands overhead.', 'Land softly with soft knees before the next rep.']::text[], 82),
  ('battle-ropes', 'Battle Ropes', 'cardio', 'Other', 'Battling_Ropes', array['Take an end in each hand and step back until there’s slight slack.', 'Sit into a quarter-squat with your chest up.', 'Drive alternating waves down the rope with your arms.', 'Keep your core braced and breathe — work in short, hard intervals.']::text[], 83),
  ('sled-push', 'Sled Push', 'cardio', 'Other', 'Sled_Push', array['Grip the uprights and lean into the sled with straight arms.', 'Keep your back flat and your hips low.', 'Drive with short, powerful steps rather than long strides.', 'Push for the set distance, then rest fully before the next run.']::text[], 84)
