-- ---------------------------------------------------------------------------
-- Seeds public.exercises from what used to be the static frontend library.
--
-- Regenerate rather than hand-edit: this file is produced from
-- src/data/exercises.ts + src/data/exerciseGuides.ts, which remain in the repo
-- as the offline fallback the app uses if the table can't be read.
--
-- Idempotent: re-running restores every built-in row to its seeded state, so an
-- admin's edits to a built-in exercise are overwritten by a replay.
-- ---------------------------------------------------------------------------
-- Generated from src/data/exercises.ts + exerciseGuides.ts. 85 rows.
on conflict (id) do update set
  name         = excluded.name,
  muscle_group = excluded.muscle_group,
  equipment    = excluded.equipment,
  demo         = excluded.demo,
  steps        = excluded.steps,
  sort_order   = excluded.sort_order,
  updated_at   = now();

